package rpg.engine.map;import org.junit.jupiter.api.*;import java.nio.file.*;import rpg.engine.core.math.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class RMapIOTest{@Test void roundTrip()throws Exception{var p=Files.createTempFile("test",".rmap");var m=new RMap("x",32,2,2,List.of(new TileLayer("g",2,2,new int[]{1,2,3,4},false)),List.of(new MapEntity("door","door",new WorldPosition(1,2,0),null,1.5)));RMapIO.write(m,p);var n=RMapIO.read(p);assertEquals(m.name(),n.name());assertArrayEquals(m.layers().get(0).tiles(),n.layers().get(0).tiles());assertEquals(m.entities().get(0).position(),n.entities().get(0).position());assertEquals(1.5,n.entities().get(0).scale());}
    @Test void readsVersion1WithoutScale()throws Exception{var p=Files.createTempFile("legacy",".rmap");RMapIO.write(new RMap("x",32,2,2,List.of(new TileLayer("g",2,2,new int[]{0,0,0,0},false)),List.of(new MapEntity("door","door",new WorldPosition(1,2,0),null,1.5))),p);byte[] v2=Files.readAllBytes(p);byte[] v1=Arrays.copyOf(v2,v2.length-8);v1[4]=0;v1[5]=0;v1[6]=0;v1[7]=1;Files.write(p,v1);var n=RMapIO.read(p);assertEquals(1.0,n.entities().get(0).scale());assertEquals("door",n.entities().get(0).prefab());assertEquals(new WorldPosition(1,2,0),n.entities().get(0).position());}}
